import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.Cdp8-jB6.js";const p=JSON.parse('{"title":"Mobile testing strategy (contributor guide)","description":"","frontmatter":{},"headers":[],"relativePath":"guides/mobile-testing.md","filePath":"guides/mobile-testing.md"}'),s={name:"guides/mobile-testing.md"};function o(n,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="mobile-testing-strategy-contributor-guide" tabindex="-1">Mobile testing strategy (contributor guide) <a class="header-anchor" href="#mobile-testing-strategy-contributor-guide" aria-label="Permalink to &quot;Mobile testing strategy (contributor guide)&quot;">​</a></h1><p><em>PRD-015 / RFC-018 · ADR-078 (stream-heavy) · ADR-079 (assetUrl spine + size budget) · v0.8</em></p><p>Companion to <strong><a href="/orrery/docs/guides/mobile-build-and-deploy">Mobile build &amp; deploy</a></strong>. That guide is how you <em>build and ship</em> the app; this one is how you <em>validate</em> it — and, crucially, how much you can validate <strong>without a device</strong>.</p><blockquote><p><strong>The insight that shapes everything below.</strong> Most of what &quot;mobile&quot; means in Orrery is <em>web</em> logic — the <code>assetUrl</code> streaming spine, deep-link routing, share-URL rebuilding, the prune. That&#39;s why it&#39;s unit- and e2e-testable off a device. The genuinely <em>native</em> surface is small: the safe-area shim, plugin invocation, and WebGL context-loss. The strategy is to push validation <strong>down</strong> to device-free layers and reserve real hardware for the irreducible native bits — shrinking &quot;manual pass&quot; to what truly needs a phone.</p></blockquote><hr><h2 id="the-pyramid" tabindex="-1">The pyramid <a class="header-anchor" href="#the-pyramid" aria-label="Permalink to &quot;The pyramid&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>What it covers</th><th>Device?</th><th>CI?</th><th>Status</th></tr></thead><tbody><tr><td><strong>0 · Unit</strong></td><td>Pure resolvers: <code>assetUrl</code>/<code>streamedUrl</code>/<code>localeBundleOrigin</code>, <code>deepLinkTarget</code>, <code>publicShareUrl</code>, the prune (fixture)</td><td>no</td><td>✅</td><td>shipped</td></tr><tr><td><strong>1 · MOBILE=1 e2e</strong></td><td>The <code>__MOBILE__</code> streaming <em>contract</em> baked into the pruned bundle: CDN-routed assets, on-device prune, en-US-only SW precache, 4K textures gated, <strong>size budget</strong></td><td>no</td><td>✅</td><td>shipped</td></tr><tr><td><strong>2 · Appium smoke</strong></td><td>The real Capacitor app on a simulator/emulator: launch, safe-area, WebGL renders, deep link, share sheet</td><td>yes</td><td>possible</td><td>roadmap</td></tr><tr><td><strong>3 · Manual checklist</strong></td><td>The irreducible hardware bits: real-notch safe-area, share UX, backgrounding→context-loss, haptics, fps</td><td>yes</td><td>no</td><td>checklist below</td></tr></tbody></table><hr><h2 id="layer-1-—-the-mobile-1-e2e-suite-device-free" tabindex="-1">Layer 1 — the MOBILE=1 e2e suite (device-free) <a class="header-anchor" href="#layer-1-—-the-mobile-1-e2e-suite-device-free" aria-label="Permalink to &quot;Layer 1 — the MOBILE=1 e2e suite (device-free)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e:mobile</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # build:mobile, then run the suite</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e:mobile:preview</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # skip the build — iterate against an existing build/</span></span></code></pre></div><p><strong>What it asserts</strong> (<code>tests/e2e/mobile/streaming.spec.ts</code>):</p><ul><li>the landing hero <code>&lt;img&gt;</code> is served <strong>absolute-to-CDN</strong> (<code>chipi.github.io/orrery/images/…</code>), not the local bundle;</li><li>every <code>/images/</code> + <code>/audio/</code> request goes to the <strong>CDN origin</strong>, never the on-device origin;</li><li>streamed + pruned buckets <strong>404 locally</strong> (<code>de.json</code>, <code>4k_moon.jpg</code>, hero image) while the on-device set is served (<code>en-US.json</code>, <code>2k_moon.jpg</code>, the downscaled base-4K <code>4k_io.jpg</code>);</li><li>the service-worker precache manifest is <strong>en-US only</strong>;</li><li>non-en locale HTML is <strong>pruned</strong>, and the precached <code>404.html</code> shell (adapter fallback + SW <code>navigateFallback</code>) carries the app bundle so those routes render client-side.</li></ul><p><strong>Two things make it correct and non-flaky:</strong></p><ol><li><strong>It serves the pruned <code>build/</code>, not <code>vite preview</code>.</strong> For a SvelteKit app <code>vite preview</code> serves the internal <code>.svelte-kit/output/</code> tree, which the prune never touches — it would serve the very files we removed. The suite uses <code>scripts/mobile/serve-build.mjs</code> (a <code>sirv</code> static server over <code>build/</code>), the exact tree Capacitor ships. Missing files 404 — that&#39;s the point.</li><li><strong>The CDN origin is stubbed</strong>, so a GitHub Pages outage never turns it red.</li></ol><p>Config: <code>playwright.mobile.config.ts</code> (separate from the browser <code>playwright.config.ts</code> — the two serve different <code>build/</code> artefacts). Override <code>PLAYWRIGHT_BASE_URL</code> to point at a device-served bundle instead of the local static server.</p><h3 id="the-size-budget-regression-gate" tabindex="-1">The size budget (regression gate) <a class="header-anchor" href="#the-size-budget-regression-gate" aria-label="Permalink to &quot;The size budget (regression gate)&quot;">​</a></h3><p><code>build:mobile</code> ends with <code>scripts/mobile/check-mobile-size-budget.mjs</code>: if the pruned <code>build/</code> exceeds <strong>65 MB</strong> the build fails and prints the largest buckets. This is what stops a leak — a re-added locale HTML tree, the images/audio buckets, or the 4K textures slipping past their gate — from silently re-bloating the OTA download. The pruned bundle is ~47 MB today; the budget sits well under the iOS 200 MB cellular-OTA cap the prune exists to clear.</p><h3 id="ci" tabindex="-1">CI <a class="header-anchor" href="#ci" aria-label="Permalink to &quot;CI&quot;">​</a></h3><p><code>.github/workflows/mobile-e2e.yml</code> runs Layer 1 after CI passes on <code>main</code> (mirrors <code>docker-e2e.yml</code>&#39;s gate). It&#39;s device-free and fast (~3–4 min), so it gates every green main push. No nightly cron — the CDN is stubbed, so there&#39;s no external state to drift.</p><hr><h2 id="layer-2-—-appium-smoke-roadmap-real-simulator-emulator" tabindex="-1">Layer 2 — Appium smoke (roadmap, real simulator/emulator) <a class="header-anchor" href="#layer-2-—-appium-smoke-roadmap-real-simulator-emulator" aria-label="Permalink to &quot;Layer 2 — Appium smoke (roadmap, real simulator/emulator)&quot;">​</a></h2><p>When heading to TestFlight / Play, add a <strong>small</strong> WebdriverIO + Appium smoke suite driving the actual Capacitor app (Appium switches into the WebView context to drive the DOM like Selenium):</p><ul><li>app launches → nav sits below the status bar (safe-area screenshot);</li><li><code>/explore</code> WebGL canvas renders non-blank;</li><li>tap a gallery → a streamed image loads;</li><li>deep link <code>orrery://fly?mission=curiosity</code> opens the route;</li><li>the share sheet appears.</li></ul><p>Keep it a <em>smoke</em> suite — Appium is slow and flake-prone. CI: Android emulator runs on Linux runners; iOS needs macOS runners or a cloud device farm (BrowserStack / Sauce App Automate / AWS Device Farm). Not built yet — this section is the design intent.</p><hr><h2 id="layer-3-—-manual-checklist-the-irreducible-hardware-bits" tabindex="-1">Layer 3 — manual checklist (the irreducible hardware bits) <a class="header-anchor" href="#layer-3-—-manual-checklist-the-irreducible-hardware-bits" aria-label="Permalink to &quot;Layer 3 — manual checklist (the irreducible hardware bits)&quot;">​</a></h2><p>Run on a real device before tagging a mobile release. These genuinely can&#39;t be automated device-free:</p><ul><li>[ ] <strong>Safe-area</strong> — nav + content clear the notch/Dynamic Island and the home indicator, portrait <strong>and</strong> landscape, on at least one notched device.</li><li>[ ] <strong>Scroll</strong> — touch scrolling works on long routes (the <code>SafeAreaViewController</code> shim force-enables it).</li><li>[ ] <strong>Share</strong> — the native share sheet opens and shares a <strong>public</strong> <code>chipi.github.io</code> URL (never <code>capacitor://localhost</code>).</li><li>[ ] <strong>Deep link</strong> — <code>orrery://fly?mission=curiosity</code> (and a <code>//</code>-in-query variant) opens the right route from cold and warm start.</li><li>[ ] <strong>Locale</strong> — set the device to German: UI + overlays render German (streamed <code>de.json</code>), and no <code>/de/*</code> route 404s.</li><li>[ ] <strong>Offline</strong> — airplane mode after first load: en-US routes + 2K textures still render; streamed imagery degrades gracefully.</li><li>[ ] <strong>WebGL context-loss</strong> — background the app during a 3D route, return after a while: the scene recovers (reload MVP).</li><li>[ ] <strong>Perf</strong> — <code>/fly</code> and <code>/explore</code> hold a smooth frame rate; textures are 2K (4K is gated off on mobile).</li><li>[ ] <strong>Splash + icons</strong> — launch splash is crisp; the home-screen icon is correct.</li></ul><hr><h2 id="what-still-needs-a-device-honest-limits" tabindex="-1">What still needs a device (honest limits) <a class="header-anchor" href="#what-still-needs-a-device-honest-limits" aria-label="Permalink to &quot;What still needs a device (honest limits)&quot;">​</a></h2><p>Even with all of the above, a few things only validate on real hardware: WKWebView context-loss <em>timing</em>, true safe-area per notch, the store share-sheet behaviour, and sustained performance. That residue is why per-scene WebGL reinit (#195) is deferred to device verification. The goal isn&#39;t zero manual — it&#39;s shrinking manual to what a phone alone can answer.</p><hr><p><em>Orrery · mobile testing · v0.8 — Layer 1 shipped; Layers 2–3 are roadmap + checklist.</em></p>`,33)])])}const g=t(s,[["render",o]]);export{p as __pageData,g as default};
